    const diasTodos = [0, 1, 2, 3, 4, 5, 6]
    const cfgDentro = { ativa: true, ausenciaAtiva: true, mensagemAusencia: 'O Financeiro atende de segunda a sexta. Retornaremos no próximo dia útil.', horarioInicio: '00:00', horarioFim: '23:59', diasSemana: diasTodos, respostaAutomatica: true, confiancaMinima: 0.6, usarConhecimento: true, usarFaqGeral: false, mensagemSemResposta: null }
